  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 13, $j$4.1 Speed, Velocity and Displacement$j$, $j${"readings": [{"title": "Hebrews 12 (King James Version)", "url": "/portal/bible/Hebrews/12"}], "body": "Motion is a change in position, and we always describe it compared with a reference point. Hebrews 12:1 says, let us run with patience the race that is set before us. A race is a good picture of motion, and the Christian life has a course to run with steady endurance.\n\nDistance is the total length of the path traveled. Displacement is the straight line change in position, including direction. If you run once around a 400 meter track and stop where you started, your distance is 400 meters but your displacement is zero. Distance has size only, while displacement has size and direction.\n\nSpeed is how fast an object moves. Average speed equals distance divided by time. A runner covers 400 meters in 50 seconds, so her average speed is 400 divided by 50, which is 8 meters per second. A car that travels 150 kilometers in 2 hours has an average speed of 75 kilometers per hour. Rearranging gives distance equals speed times time, and time equals distance divided by speed. If you ride at 6 meters per second for 30 seconds, you travel 180 meters.\n\nVelocity is speed in a given direction. A car moving at 20 meters per second north has a different velocity from a car moving at 20 meters per second south, even though their speeds are the same. Velocity is a vector, which has both size and direction, and speed is a scalar, which has size only.\n\nA distance time graph shows motion. A straight line that slopes upward shows constant speed. The steeper the line, the greater the speed. A flat line shows that the object is at rest. A curved line shows a changing speed.\n\nYour task: (1) Tell distance from displacement. (2) Calculate average speed and distance. (3) Read a distance time graph.\n\nFlorida standards: SC.912.P.12.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.12", "script": "Welcome back. Listen, Hebrews 12:1 says, let us run with patience the race that is set before us. A race is a good picture of motion, and the Christian life has a course to run with steady endurance.\n\nNow watch this. Distance is the total length of the path. Displacement is the straight line change in position, with direction. If you run once around a 400 meter track, your distance is 400 meters but your displacement is zero.\n\nLook at speed. Average speed is distance divided by time. A runner covers 400 meters in 50 seconds, so her speed is 8 meters per second. A car that travels 150 kilometers in 2 hours averages 75 kilometers per hour. Distance equals speed times time, so 6 meters per second for 30 seconds is 180 meters.\n\nVelocity is speed in a given direction. Twenty meters per second north and twenty meters per second south are different velocities with the same speed.\n\nOn a distance time graph, the steeper the line, the greater the speed. A flat line means the object is at rest.\n\nYour task is to tell distance from displacement, calculate speed and read a graph. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.1 Speed, Velocity and Displacement$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 14, $j$4.2 Acceleration and Free Fall$j$, $j${"readings": [{"title": "Ecclesiastes 9 (King James Version)", "url": "/portal/bible/Ecclesiastes/9"}], "body": "Acceleration is how quickly velocity changes. Ecclesiastes 9:11 says, the race is not to the swift, nor the battle to the strong. Speed alone does not decide every outcome, and we remember that God rules over all.\n\nAcceleration equals the final velocity minus the initial velocity, divided by the time. A car speeds up from 0 to 20 meters per second in 5 seconds. The change in velocity is 20, and 20 divided by 5 is 4, so the acceleration is 4 meters per second squared. That means the velocity increases by 4 meters per second every second.\n\nSlowing down is also acceleration. A cyclist slows from 12 meters per second to 4 meters per second in 4 seconds. The change in velocity is negative 8, so the acceleration is negative 8 divided by 4, which is negative 2 meters per second squared. The negative sign tells us the acceleration points opposite the motion.\n\nBecause velocity includes direction, an object accelerates when it speeds up, slows down or changes direction. A car going around a curve at a steady speed is still accelerating, because its direction keeps changing. The same is true of a planet in orbit.\n\nFree fall is motion with only gravity acting. Near Earth's surface, an object in free fall gains about 9.8 meters per second of speed every second, so the acceleration is 9.8 meters per second squared. Starting from rest, after 1 second the speed is 9.8 meters per second, and after 3 seconds it is 29.4 meters per second. In air, resistance slows the fall. A falling skydiver reaches terminal velocity when air resistance balances the weight, and the speed stops increasing.\n\nA speed time graph helps. A rising line shows speeding up, and its slope is the acceleration. A flat line shows constant speed.\n\nYour task: (1) Calculate acceleration. (2) Explain how a car at constant speed on a curve accelerates. (3) Find the speed of a falling object after a given time.\n\nFlorida standards: SC.912.P.12.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.12", "script": "Welcome back. Listen, Ecclesiastes 9:11 says, the race is not to the swift, nor the battle to the strong. Speed alone does not decide every outcome, and we remember that God rules over all.\n\nNow watch this. Acceleration is the final velocity minus the initial velocity, divided by the time. A car goes from 0 to 20 meters per second in 5 seconds. That is 20 divided by 5, so the acceleration is 4 meters per second squared.\n\nSlowing down is acceleration too. A cyclist slows from 12 to 4 meters per second in 4 seconds. The change is negative 8, so the acceleration is negative 2 meters per second squared.\n\nVelocity includes direction, so an object also accelerates when it changes direction. A car on a curve at steady speed is accelerating.\n\nFree fall is motion with only gravity acting. Near Earth's surface the acceleration is about 9.8 meters per second squared. From rest, the speed after 3 seconds is 29.4 meters per second. Air resistance slows the fall, and a skydiver reaches terminal velocity when air resistance balances weight.\n\nYour task is to calculate acceleration, explain acceleration on a curve and find a falling speed. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.2 Acceleration and Free Fall$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 15, $j$4.3 Forces and Newton's Laws of Motion$j$, $j${"readings": [{"title": "Job 26 (King James Version)", "url": "/portal/bible/Job/26"}], "body": "A force is a push or a pull, measured in newtons. Job 26:7 says of God, He stretcheth out the north over the empty place, and hangeth the earth upon nothing. The laws of motion describe how the Creator governs everything from a rolling ball to the planets.\n\nForces combine. The net force is the sum of all the forces on an object, taking direction into account. Balanced forces cancel, so the net force is zero and the motion does not change. Unbalanced forces change the motion.\n\nNewton's first law says that an object at rest stays at rest, and an object in motion stays in motion at a constant velocity, unless an unbalanced force acts on it. This tendency is inertia, and the more mass an object has, the more inertia it has. Passengers lurch forward when a car brakes because their bodies keep moving, which is why seat belts matter.\n\nNewton's second law says that acceleration equals the net force divided by the mass, or force equals mass times acceleration. A 2 kilogram cart that accelerates at 3 meters per second squared has a net force of 2 times 3, which is 6 newtons. A net force of 60 newtons on a 12 kilogram object gives an acceleration of 5 meters per second squared. A bigger force gives a bigger acceleration, and a bigger mass gives a smaller acceleration.\n\nNewton's third law says that for every action there is an equal and opposite reaction. When you push on a wall, the wall pushes back with the same force. The two forces act on different objects, so they do not cancel. A rocket moves forward because it pushes hot gas backward.\n\nFriction is a force that opposes motion between surfaces. Static friction holds an object that is not moving, sliding friction acts when surfaces slide, and rolling friction acts on wheels. Friction produces heat and wears surfaces, yet without it we could not walk or stop a car.\n\nYour task: (1) State each of Newton's laws with an example. (2) Use force equals mass times acceleration. (3) Explain why action and reaction forces do not cancel.\n\nFlorida standards: SC.912.P.12.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.12", "script": "Welcome back. Listen, Job 26:7 says of God, He stretcheth out the north over the empty place, and hangeth the earth upon nothing. The laws of motion describe how the Creator governs everything from a rolling ball to the planets.\n\nNow watch this. The net force is the sum of all forces on an object. Balanced forces cancel and the motion does not change. Unbalanced forces change the motion.\n\nNewton's first law says an object keeps its motion unless an unbalanced force acts on it. That tendency is inertia, and more mass means more inertia. Seat belts matter because your body keeps moving when the car stops.\n\nNewton's second law says force equals mass times acceleration. A 2 kilogram cart accelerating at 3 meters per second squared has a net force of 6 newtons. Sixty newtons on a 12 kilogram object gives 5 meters per second squared.\n\nNewton's third law says for every action there is an equal and opposite reaction. When you push a wall, it pushes back. The forces act on different objects, so they do not cancel. A rocket moves forward by pushing gas backward.\n\nFriction opposes motion. Without it we could not walk or stop a car.\n\nYour task is to state the three laws, use force equals mass times acceleration and explain action and reaction. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.3 Forces and Newton's Laws of Motion$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 16, $j$4.4 Gravity, Momentum and Orbits$j$, $j${"readings": [{"title": "Psalm 8 (King James Version)", "url": "/portal/bible/Psalms/8"}], "body": "Gravity is the force that pulls masses toward each other. Psalm 8:3 says, When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained. The same gravity that holds us to the ground holds the Moon in its path.\n\nNewton's law of universal gravitation says every mass attracts every other mass. The force is greater when the masses are larger and weaker when the objects are farther apart. If the distance doubles, the force becomes one fourth as strong. Because Earth is so massive, we feel its pull strongly.\n\nWeight is the force of gravity on an object, equal to mass times the acceleration due to gravity. A 50 kilogram person has a weight of 50 times 9.8, which is 490 newtons. The Moon has less mass, so its gravity is about one sixth of Earth's. A 50 kilogram person has the same mass on the Moon but a much smaller weight. Without air resistance, all objects fall with the same acceleration regardless of mass. In 1971 an astronaut on the Moon dropped a hammer and a feather together, and they landed at the same time.\n\nAn orbit is a path in which an object falls around another object. A satellite moves sideways so fast that as it falls toward Earth, the ground curves away beneath it. Gravity keeps pulling it into a curved path.\n\nMomentum equals mass times velocity. A 1000 kilogram car moving at 20 meters per second has a momentum of 20,000 kilogram meters per second. Momentum is conserved in a collision when no outside forces act, so the total momentum before equals the total after. A 2 kilogram cart moving at 3 meters per second has a momentum of 6. If it sticks to a 1 kilogram cart at rest, the total momentum is still 6, and the combined mass of 3 kilograms moves at 6 divided by 3, which is 2 meters per second.\n\nYour task: (1) Explain how mass and distance affect gravity. (2) Calculate weight and momentum. (3) Use conservation of momentum in a collision.\n\nFlorida standards: SC.912.P.12.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.12", "script": "Welcome back. Listen, Psalm 8:3 says, When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained. The same gravity that holds us to the ground holds the Moon in its path.\n\nNow watch this. Every mass attracts every other mass. The force grows with larger masses and weakens with distance. If the distance doubles, the force becomes one fourth as strong.\n\nWeight is mass times the acceleration due to gravity. A 50 kilogram person weighs 50 times 9.8, which is 490 newtons. The Moon's gravity is about one sixth of Earth's. Without air resistance, all objects fall with the same acceleration. An astronaut on the Moon dropped a hammer and a feather together and they landed at the same time.\n\nAn orbit is a path in which an object falls around another. A satellite moves sideways so fast that the ground curves away as it falls.\n\nMomentum is mass times velocity. A 1000 kilogram car at 20 meters per second has a momentum of 20,000. In a collision the total momentum is conserved. A 2 kilogram cart at 3 meters per second sticks to a 1 kilogram cart at rest. Total momentum is 6, and the 3 kilograms move at 2 meters per second.\n\nYour task is to explain gravity, calculate weight and momentum and use conservation of momentum. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$4.4 Gravity, Momentum and Orbits$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 4, $j$Assessment 4: Motion and Forces$j$, $j${"prompt": "Write a report of at least 250 words on motion and forces. Use complete sentences, show every calculation and label each part. Job 26:7 says, He stretcheth out the north over the empty place, and hangeth the earth upon nothing.\n\nPart 1: A cyclist rides 90 kilometers in 3 hours. Find the average speed. Then explain the difference between distance and displacement using a runner who circles a 400 meter track once.\nPart 2: A car speeds up from 5 meters per second to 25 meters per second in 4 seconds. Find its acceleration. Then find the speed of a ball dropped from rest after 2 seconds of free fall, using 9.8 meters per second squared.\nPart 3: State Newton's three laws and give one everyday example of each. Find the net force needed to accelerate a 1500 kilogram car at 2 meters per second squared.\nPart 4: Find the weight in newtons of a 60 kilogram student on Earth. Explain what happens to the force of gravity between two objects when the distance between them doubles.\nPart 5: A 1 kilogram cart moving at 4 meters per second hits and sticks to a 3 kilogram cart at rest. Find their speed afterward. Explain how seat belts and Job 26:7 show care in using the laws of motion.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 15 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 4: Motion and Forces$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 4, $j$Discussion 4: Forces and Finishing the Race$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time you had to keep going at a steady pace, in sports, school or life, (2) explains Newton's first law and how it relates to staying in motion or staying at rest, (3) explains how safety devices such as seat belts use the laws of motion to protect people, and (4) connects your answer to Hebrews 12:1, Job 26:7 or Psalm 8:3. Then write a respectful reply of at least 40 words to another student's post, or answer this question: What does it mean that God hangs the earth upon nothing, and how does gravity describe His order? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 4: Forces and Finishing the Race$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 16, $j$Check 4.1: Speed, Velocity and Displacement$j$, $j${"questions": [{"q": "Average speed equals:", "options": ["Time divided by distance", "Distance times time", "Distance divided by time", "Mass divided by volume"]}, {"q": "A runner covers 400 meters in 50 seconds. Her average speed is:", "options": ["8 m/s", "20,000 m/s", "0.125 m/s", "350 m/s"]}, {"q": "Velocity differs from speed because velocity includes:", "options": ["Energy", "Time only", "Mass", "Direction"]}, {"q": "On a distance time graph, a steeper line means:", "options": ["No motion", "Greater mass", "Lower speed", "Greater speed"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Speed, Velocity and Displacement$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3}'::int[], array[$j$Speed is distance per unit of time.$j$,$j$400 divided by 50 equals 8.$j$,$j$Velocity is speed with direction.$j$,$j$The slope of the line is the speed.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.1: Speed, Velocity and Displacement$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 17, $j$Check 4.2: Acceleration and Free Fall$j$, $j${"questions": [{"q": "Acceleration is the rate of change of:", "options": ["Mass", "Velocity", "Force", "Distance"]}, {"q": "A car speeds up from 0 to 20 m/s in 5 seconds. Its acceleration is:", "options": ["0.25 m/s squared", "100 m/s squared", "4 m/s squared", "15 m/s squared"]}, {"q": "An object moving in a circle at constant speed is accelerating because:", "options": ["Its mass is changing", "Its speed is changing", "The direction of its velocity is changing", "Its weight is changing"]}, {"q": "Near Earth's surface, an object in free fall accelerates at about:", "options": ["1 m/s squared", "9.8 m/s squared", "0 m/s squared", "98 m/s squared"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Acceleration and Free Fall$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,1}'::int[], array[$j$Acceleration measures how quickly velocity changes.$j$,$j$20 divided by 5 equals 4.$j$,$j$Changing direction means changing velocity.$j$,$j$Gravity gives about 9.8 meters per second squared.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.2: Acceleration and Free Fall$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 18, $j$Check 4.3: Forces and Newton's Laws of Motion$j$, $j${"questions": [{"q": "Newton's first law says an object at rest stays at rest unless acted on by:", "options": ["A balanced force", "Its own color", "An unbalanced force", "Its temperature"]}, {"q": "A 2 kg cart accelerates at 3 m/s squared. The net force is:", "options": ["0.67 N", "6 N", "5 N", "1.5 N"]}, {"q": "When you push on a wall, the wall pushes back with an equal force. This is Newton's:", "options": ["First law", "Third law", "Law of gravity", "Second law"]}, {"q": "Which object has the most inertia?", "options": ["A 2 kg book", "A 1 kg ball", "A 10 kg box", "A 5 gram marble"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Forces and Newton's Laws of Motion$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,1,2}'::int[], array[$j$An unbalanced force changes motion.$j$,$j$Force equals 2 times 3.$j$,$j$Action and reaction describe the third law.$j$,$j$Inertia increases with mass.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.3: Forces and Newton's Laws of Motion$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 19, $j$Check 4.4: Gravity, Momentum and Orbits$j$, $j${"questions": [{"q": "The force of gravity between two objects increases when:", "options": ["Their masses increase or the distance between them decreases", "The distance between them increases", "They move faster", "Their masses decrease"]}, {"q": "A 50 kg person has a weight on Earth of about:", "options": ["5 N", "4900 N", "50 N", "490 N"]}, {"q": "Momentum equals:", "options": ["Force times distance", "Mass times velocity", "Mass divided by velocity", "Velocity divided by time"]}, {"q": "A 2 kg cart moving at 3 m/s sticks to a 1 kg cart at rest. Their speed afterward is:", "options": ["3 m/s", "1 m/s", "6 m/s", "2 m/s"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Gravity, Momentum and Orbits$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,3}'::int[], array[$j$Gravity grows with mass and weakens with distance.$j$,$j$50 times 9.8 equals 490.$j$,$j$Momentum is mass multiplied by velocity.$j$,$j$Total momentum 6 divided by total mass 3 equals 2.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 4.4: Gravity, Momentum and Orbits$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 20, $j$Unit Quiz 4: Motion and Forces$j$, $j${"questions": [{"q": "A car travels 150 km in 2 hours. Its average speed is:", "options": ["300 km/h", "75 km/h", "152 km/h", "0.013 km/h"]}, {"q": "A runner goes once around a 400 meter track and ends where she started. Her displacement is:", "options": ["800 meters", "0 meters", "400 meters", "200 meters"]}, {"q": "A cyclist slows from 12 m/s to 4 m/s in 4 seconds. Her acceleration is:", "options": ["Positive 3 m/s squared", "Negative 2 m/s squared", "Negative 8 m/s squared", "Positive 2 m/s squared"]}, {"q": "A net force of 20 N acts on a 4 kg object. Its acceleration is:", "options": ["80 m/s squared", "5 m/s squared", "0.2 m/s squared", "16 m/s squared"]}, {"q": "Which law explains why passengers lurch forward when a car brakes suddenly?", "options": ["The law of conservation of mass", "Newton's third law", "Newton's first law", "The law of reflection"]}, {"q": "The weight of a 10 kg object near Earth's surface is about:", "options": ["9.8 N", "10 N", "980 N", "98 N"]}, {"q": "A 1000 kg car moves at 20 m/s. Its momentum is:", "options": ["1020 kilogram meters per second", "20,000 kilogram meters per second", "50 kilogram meters per second", "200 kilogram meters per second"]}, {"q": "Without air resistance, a heavy ball and a light ball dropped together:", "options": ["Hit the ground at the same time", "Land with the heavy one first", "Never land", "Land with the light one first"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Motion and Forces$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,1,2,3,1,0}'::int[], array[$j$150 divided by 2 equals 75.$j$,$j$She ended at the starting point.$j$,$j$Negative 8 divided by 4 equals negative 2.$j$,$j$20 divided by 4 equals 5.$j$,$j$Inertia keeps the passengers moving.$j$,$j$10 times 9.8 equals 98.$j$,$j$1000 times 20 equals 20,000.$j$,$j$All objects fall with the same acceleration.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 4: Motion and Forces$j$ on conflict (item_id) do nothing;
